import{_ as s,a0 as l,w as d,s as p,ao as o,I as r,a1 as i,A as n,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const O=JSON.parse('{"title":"EndeavourOS Artemis 22.06 發佈，帶來更好的 ARM 支持 | LCTT x X-CMD","titleTemplate":false,"description":"EndeavourOS Artemis 22.06 發佈，帶來更好的 ARM 支持 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"EndeavourOS Artemis 22.06 發佈，帶來更好的 ARM 支持 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"EndeavourOS Artemis 22.06 發佈，帶來更好的 ARM 支持 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230711.0 ⭐️ EndeavourOS Artemis Released with Better ARM Support and Updates","title":"EndeavourOS Artemis 22.06 發佈，帶來更好的 ARM 支持","tag":"202307","desc":""},"relativePath":"202307/20230711.0 ⭐️ EndeavourOS Artemis Released with Better ARM Support and Updates.md","filePath":"[post].md"}'),u={name:"202307/20230711.0 ⭐️ EndeavourOS Artemis Released with Better ARM Support and Updates.md"};function m(A,e,f,S,v,b){const a=l("Link");return d(),p("div",null,[e[23]||(e[23]=o('<h1 id="endeavouros-artemis-22-06-發佈-帶來更好的-arm-支持" tabindex="-1">EndeavourOS Artemis 22.06 發佈，帶來更好的 ARM 支持 <a class="header-anchor" href="#endeavouros-artemis-22-06-發佈-帶來更好的-arm-支持" aria-label="Permalink to “EndeavourOS Artemis 22.06 發佈，帶來更好的 ARM 支持”">​</a></h1><blockquote><p>EndeavourOS 團隊發佈了 6 月份的 22.06 版本（“Artemis”），帶來了更好的 ARM 支持，最新內核等功能。我們在本文中總結髮布內容。</p></blockquote><p><img src="https://debugpointnews.com/wp-content/uploads/2022/06/EndeavourOS-Artemis-22.06-Desktop-Xfce.jpg" alt="EndeavourOS Artemis 22.06 桌面（Xfce）"></p><h3 id="endeavouros-artemis-發佈-22-06" tabindex="-1">EndeavourOS Artemis 發佈：22.06 <a class="header-anchor" href="#endeavouros-artemis-發佈-22-06" aria-label="Permalink to “EndeavourOS Artemis 發佈：22.06”">​</a></h3>',4)),r("p",null,[i(a,{href:"https://debugpointnews.com/tag/endeavouros/"},{default:n(()=>[...e[0]||(e[0]=[t("EndeavourOS",-1)])]),_:1}),e[1]||(e[1]=t(" Artemis 版本（22.06）以 NASA 即將進行的月球任務 “",-1)),e[2]||(e[2]=r("ruby",null,[t("阿爾忒彌斯"),r("rt",null,"Artemis")],-1)),e[3]||(e[3]=t("” 命名，為這個出色的 Linux 發行版帶來了定期的 Arch Linux 更新。",-1))]),e[24]||(e[24]=o('<h4 id="arm-更新" tabindex="-1">ARM 更新 <a class="header-anchor" href="#arm-更新" aria-label="Permalink to “ARM 更新”">​</a></h4><p>EndeavourOS 的 ARM 版本首次發佈於 2020 年，成為了該團隊的長期目標。這個目標是為用户提供一種穩定的基於 Arch Linux 的 ARM 變體發行版，注重 “友好性” 和 “功能性”。在 22.06 中，ARM ISO 被稱為 “更接近主要發佈版本”。</p><p>這次月度更新中的重要改變是在 ARM 安裝過程中引入了 Calamares 安裝程序。此外，ARM 安裝的快捷方式被放置在其標誌性的 “<ruby>歡迎<rt>Welcome</rt></ruby>” 應用程序中。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2022/06/EndeavourOS-Artemis-brings-better-accessibility-for-ARM.jpg" alt="EndeavourOS Artemis 提供更好的 ARM 可訪問性"></p><p>然而，ARM 中的 Calamares 安裝程序仍處於 BETA 階段。這意味着在安裝時需要謹慎，目前支持的設備有：Odroid N2/N2+ 和樹莓派。</p><p>此外，ARM 安裝中的桌面環境和軟件包已經更加精細調整以與上游同步。因此，你可以在樹莓派設備上獲得最新和最優秀的軟件。</p><h4 id="其他變化" tabindex="-1">其他變化 <a class="header-anchor" href="#其他變化" aria-label="Permalink to “其他變化”">​</a></h4><p>除了上述變更外，EndeavourOS 22.06 版本還帶來了 Linux 內核 5.18.5。截至撰寫本文時，Linux 內核 5.19 尚未發佈。因此，在這個出色發行版的下一個 ISO 更新中可能會包含該版本。</p><p>此次發佈中的其他值得注意的變更包括將 pipewire-media-session 替換為 wireplumber，並對 Xfce 離線安裝進行了代碼清理。此外，著名的 Budgie 控制中心現在在該發行版的 Budgie 版本中已經可用，以提供原生 Budgie 的體驗。</p><p>總結起來，這個版本的主要變更如下：</p><ul><li>ARM ISO 更接近主要發佈版本</li><li>ARM 安裝中可使用 Calamares 安裝程序</li><li>Linux 內核 5.18.5</li><li>Xfce 4.16 版本（旗艦版）進行了安裝程序代碼清理</li><li>Budgie 控制中心現在在 EndeavourOS 存儲庫中可用</li><li>在在線安裝之前提供更好的密鑰環同步問題控制</li><li>添加了降級軟件包的支持 - eos-downgrade</li><li>Firefox 101.x</li></ul><h3 id="簡單測評" tabindex="-1">簡單測評 <a class="header-anchor" href="#簡單測評" aria-label="Permalink to “簡單測評”">​</a></h3><p>我們在虛擬機環境中測試了這個發行版。Xfce 離線安裝的下載大小為 1.8 GB，並且安裝過程很順利。鏡像下週速度非常快。</p><p>首先，<ruby>立付<rt>Live</rt></ruby> 桌面可以讓你啓動安裝 - 支持離線和在線兩種。離線安裝將安裝 Xfce 桌面環境。此外，如果你有互聯網連接，可以使用在線安裝選項安裝其他桌面環境和窗口管理器。</p><p>其次，通過 Calamares 安裝非常順利。儘管最近發佈了 “archinstall”，它使 Arch Linux 的安裝變得非常容易。我必須説，EndeavourOS 正在成為 Arch Linux 世界中的 “Linux Mint”。</p><p>安裝完成後，桌面將通過 “歡迎” 應用程序向你表示歡迎。如果你是新用户，“歡迎” 應用程序為你提供一個入口點，用於執行各種桌面任務。</p><p>性能經過了良好優化。在空閒狀態下，此版本在 Xfce 桌面上使用 2% 到 3% 的 CPU 和約 900 MB 的 RAM。這是一個不錯的指標。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2022/06/EndeavourOS-Artemis-Performance.jpg" alt="EndeavourOS Artemis 性能"></p><p>此外，如果你打開更多應用程序進行工作，資源消耗可能會增加。</p><p>最後，EndeavourOS Artemis Xfce 版默認安裝佔用 4.2 GB 的磁盤空間。</p><h3 id="下載" tabindex="-1">下載 <a class="header-anchor" href="#下載" aria-label="Permalink to “下載”">​</a></h3><p>你可以在此頁面下載官方發佈版本，其中包含鏡像和種子文件。</p>',22)),r("blockquote",null,[r("p",null,[r("strong",null,[i(a,{href:"https://endeavouros.com/latest-release/"},{default:n(()=>[...e[4]||(e[4]=[t("下載 EndeavourOS",-1)])]),_:1})])])]),r("p",null,[e[6]||(e[6]=t("參考自官方 ",-1)),i(a,{href:"https://endeavouros.com/news/artemis-is-launched/"},{default:n(()=>[...e[5]||(e[5]=[t("發佈公告",-1)])]),_:1}),e[7]||(e[7]=t("。",-1))]),e[25]||(e[25]=r("hr",null,null,-1)),r("p",null,[e[9]||(e[9]=t("via: ",-1)),i(a,{href:"https://debugpointnews.com/endeavouros-artemis/"},{default:n(()=>[...e[8]||(e[8]=[t("https://debugpointnews.com/endeavouros-artemis/",-1)])]),_:1})]),r("p",null,[e[14]||(e[14]=t("作者：",-1)),i(a,{href:"https://debugpointnews.com/author/dpicubegmail-com/"},{default:n(()=>[...e[10]||(e[10]=[t("arindam",-1)])]),_:1}),e[15]||(e[15]=t(" 選題：",-1)),i(a,{href:"https://github.com/lkxed/"},{default:n(()=>[...e[11]||(e[11]=[t("lkxed",-1)])]),_:1}),e[16]||(e[16]=t(" 譯者：",-1)),i(a,{href:"https://github.com/%E8%AD%AF%E8%80%85ID"},{default:n(()=>[...e[12]||(e[12]=[t("譯者ID",-1)])]),_:1}),e[17]||(e[17]=t(" 校對：",-1)),i(a,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:n(()=>[...e[13]||(e[13]=[t("校對者ID",-1)])]),_:1})]),r("p",null,[e[20]||(e[20]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[18]||(e[18]=[t("LCTT",-1)])]),_:1}),e[21]||(e[21]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[19]||(e[19]=[t("Linux中國",-1)])]),_:1}),e[22]||(e[22]=t(" 榮譽推出",-1))])])}const R=s(u,[["render",m]]);export{O as __pageData,R as default};
